class MeineListe {
   private Knoten anfang; 


   //ändere Knoten knoten -> DatenElement daten
   boolean add(DatenElement daten) {
      //anfang noch null oder nicht 
      if(anfang == null) {
         anfang = new Knoten(daten);;
      } else {
         anfang.add(daten); 
      }
      return true; 
   }

   boolean entfernen(DatenElement daten) {
      //Liste nicht leer
      if(anfang != null) {
         // speichere anfang zwischen
         if(anfang.getDaten() == daten) {
            anfang = anfang.getNachfolger();
            return true; 
         } else {
            //Rekursion
            return anfang.entfernen(daten);
         }
      } else {
         return false;
      }

   }

   Knoten getAnfang() {
      return anfang;
   }

   void setAnfang(Knoten anfang) {
      this.anfang = anfang;
   }


}

class Knoten {
   private Knoten nachfolger;
   private DatenElement daten; 

   Knoten(DatenElement daten) {
      this.daten = daten;
   }

   DatenElement getDaten() {
      return daten;
   }

   void setDaten(DatenElement daten) {
      this.daten = daten;
   }

   Knoten getNachfolger() {
      return nachfolger;
   }

   void setNachfolger(Knoten nachfolger) {
      this.nachfolger = nachfolger;
   }

   boolean add(DatenElement daten) {
      //ist schon letzter Knoten
      if(nachfolger == null) {
         nachfolger = new Knoten(daten); 
         return true;
      } else {
         // nicht letzer Knoten --> Rekursion
         return nachfolger.add(daten);
      }
   }



   boolean entfernen(DatenElement daten) {
      //gibt es noch einen Nachfolger
      if(nachfolger != null) {
         //hat mein Nachfolger die passenden Daten?
         if(nachfolger.getDaten() == daten) {
            //ja, dann überspringe ich ihn und hole mir seinen Nachfolger
            nachfolger = nachfolger.getNachfolger(); 
            // und war erfolgreich
            return true;
         } else {
            // Rekursion --> weitergeben der Aufgabe 
            return nachfolger.entfernen(daten); 
         }
      } else {
         //kein Nachfolger aber nicht gefunden --> falsch
         return false; 
      }
   }


}

class Taxi implements DatenElement {

   int autonummer;
   String fahrerName; 

   //Konstruktor
   Taxi(int autonummer, String fahrerName) {
      this.autonummer = autonummer;
      this.fahrerName = fahrerName;
   }

   String getFahrerName() {
      return fahrerName;
   }

   void setFahrerName(String fahrerName) {
      this.fahrerName = fahrerName;
   }

   int getAutonummer() {
      return autonummer;
   }

   void setAutonummer(int autonummer) {
      this.autonummer = autonummer;
   }

   public String toString() {
      return "Autonummer: " + autonummer + " Fahrername: " + fahrerName; 
   }
}

Taxi t1 = new Taxi(12, "Stefan");
Taxi t2 = new Taxi(13, "Haunschild");

println(t1.toString());
println(t2.toString());

